<script setup lang="ts">
import GameSelect from './GameSelect.vue'
import {labelOptions,qualityOptions} from './select-options'
import {watch,ref} from 'vue'
import {statLabels} from '../shared/hero-growth'
const props=defineProps<{form:any}>(),emit=defineEmits<{invalid:[boolean]}>(),setText=ref('[]'),setError=ref('')
const setExample='例如：'+JSON.stringify([{count:3,bonuses:{meleeDefense:6,rangedDefense:6}}])
watch(()=>props.form.effectConfig,cfg=>{if(!cfg)return;cfg.flatBonuses??={};setText.value=JSON.stringify(cfg.setBonuses??[],null,2);setError.value='';emit('invalid',false)},{immediate:true})
function updateSets(){try{const parsed=JSON.parse(setText.value);if(!Array.isArray(parsed))throw Error();props.form.effectConfig.setBonuses=parsed;setError.value='';emit('invalid',false)}catch{setError.value='套装属性必须是有效的 JSON 数组';emit('invalid',true)}}
</script>
<template><section v-if="form.effectConfig" class="effect-editor"><h3>图标与培养配置</h3><p class="fineprint">官方图鉴提供名称与图片；未考证的单件数值、门槛、成长及套装数值使用单机配置，可在此校准。</p><div class="fields"><label>本地图标路径<input v-model="form.effectConfig.icon" placeholder="/art/official/trea_8000.jpg"></label><label>资料状态<GameSelect v-model="form.effectConfig.sourceStatus" label="资料状态" :options="labelOptions({VERIFIED:'已核实',ESTIMATED:'待校准',DIY:'自定义'})"/></label><template v-if="['EQUIPMENT','TREASURE'].includes(form.itemType)"><label>实力要求<input v-model.number="form.effectConfig.requiredStrength" type="number" min="0" max="1000" placeholder="0"></label><label>每次精炼基础增幅（0.2 为 20%）<input v-model.number="form.effectConfig.refineStep" type="number" min="0" max="10" step="0.01" placeholder="0.2"></label><label>逐级精炼倍率<button v-if="!form.effectConfig.refineMultipliers" type="button" @click="form.effectConfig.refineMultipliers=Array.from({length:10},(_,n)=>Number((1+n*(form.effectConfig.refineStep??0.2)).toFixed(4)))">启用单件等级表</button><button v-else type="button" @click="delete form.effectConfig.refineMultipliers">改用线性成长</button></label><template v-if="form.effectConfig.refineMultipliers"><label v-for="(_,level) in form.effectConfig.refineMultipliers" :key="'refine-'+level">+{{level}} 属性倍率<input v-model.number="form.effectConfig.refineMultipliers[level]" type="number" :min="level===0?1:form.effectConfig.refineMultipliers[Number(level)-1]" :max="level===0?1:10000" step="0.0001" required></label></template><label v-if="form.itemType==='EQUIPMENT'">新装备初始孔数<input v-model.number="form.effectConfig.initialSockets" type="number" min="0" max="3" placeholder="0"></label><label v-for="(name,key) in statLabels" :key="key">{{name}}固定加成<input v-model.number="form.effectConfig.flatBonuses[key]" type="number" min="0" max="10000000" placeholder="0"></label><label>套装标识<input v-model="form.effectConfig.setCode" maxlength="64" placeholder="同套装使用相同标识"></label></template><template v-if="form.itemType==='MATERIAL'"><label>宝石属性<GameSelect v-model="form.effectConfig.gemStat" label="宝石属性" :options="[{id:undefined,label:'非宝石材料'},...labelOptions(statLabels)]"/></label><label v-if="form.effectConfig.gemStat&&!form.effectConfig.gemBonuses">镶嵌固定加成<input v-model.number="form.effectConfig.gemAmount" type="number" min="1" max="100000000" required></label><template v-if="form.effectConfig.gemStat"><label>宝石系别<input v-model="form.effectConfig.gemFamily" placeholder="xiuluo" maxlength="32"></label><label>宝石等级<input v-model.number="form.effectConfig.gemLevel" type="number" min="1" max="8"></label><label v-for="(value,key) in form.effectConfig.gemBonuses" :key="key">{{statLabels[key as keyof typeof statLabels]}}固定加成<input v-model.number="form.effectConfig.gemBonuses[key]" type="number" min="1" max="100000000" @input="key===form.effectConfig.gemStat&&(form.effectConfig.gemAmount=Number(($event.target as HTMLInputElement).value))"></label></template></template></div><label v-if="form.itemType==='EQUIPMENT'">套装效果（JSON，按穿戴槽位计数，左右手镯及戒指分别计件，取达到的最高档）<textarea v-model="setText" @input="updateSets" rows="6"></textarea><small>{{setError||setExample}}</small></label></section></template>
<style scoped>.effect-editor{margin-block:18px;padding-top:16px;border-top:1px solid #54452e}.effect-editor textarea{width:100%;font:12px/1.6 monospace}.effect-editor small{overflow-wrap:anywhere}</style>
